"""Request and response types for the TypeSafe-compatible System One API.

Shapes follow TypeSafe's public OpenAPI description (notes/typesafe_openapi.json) and the
behaviour of the official Python SDK (msgspec structs). Extra keys are tolerated everywhere;
Score legend and probability keys are integer-parseable strings.
"""
from __future__ import annotations

from typing import Any, Literal, Union

from pydantic import BaseModel, ConfigDict, Field, model_validator

Entry = Union[str, dict[str, Any], list[Any], None]

MAX_CHOICE_OPTIONS = 255
MAX_SCORE_LEVELS = 10


class _Lenient(BaseModel):
    model_config = ConfigDict(extra="allow")


class NoulCriteria(_Lenient):
    true: Entry = None
    false: Entry = None


class NoulQuestion(_Lenient):
    type: Literal["noul"]
    instructions: Entry = None
    criteria: NoulCriteria | None = None


class ChoiceQuestion(_Lenient):
    type: Literal["choice"]
    instructions: Entry = None
    criteria: dict[str, Entry]

    @model_validator(mode="after")
    def _check(self) -> "ChoiceQuestion":
        if not self.criteria:
            raise ValueError("choice question needs at least one option in criteria")
        if len(self.criteria) > MAX_CHOICE_OPTIONS:
            raise ValueError(f"choice question has {len(self.criteria)} options, maximum is {MAX_CHOICE_OPTIONS}")
        return self


class ScoreQuestion(_Lenient):
    type: Literal["score"]
    instructions: Entry = None
    criteria: list[Entry]

    @model_validator(mode="after")
    def _check(self) -> "ScoreQuestion":
        if not self.criteria:
            raise ValueError("score question needs at least one level in criteria")
        if len(self.criteria) > MAX_SCORE_LEVELS:
            raise ValueError(f"score question has {len(self.criteria)} levels, maximum is {MAX_SCORE_LEVELS}")
        return self


Question = Union[NoulQuestion, ChoiceQuestion, ScoreQuestion]


class SystemOneRequest(_Lenient):
    state: Any = None
    model: str = "jev-latest"
    questions: dict[str, Question] = Field(discriminator=None)

    @model_validator(mode="after")
    def _check(self) -> "SystemOneRequest":
        if not self.questions:
            raise ValueError("at least one question is required")
        return self


class NoulAnswer(BaseModel):
    type: Literal["noul"] = "noul"
    noul: float


class ChoiceAnswer(BaseModel):
    type: Literal["choice"] = "choice"
    choice: str
    probabilities: dict[str, float]
    confidence: float


class ScoreAnswer(BaseModel):
    type: Literal["score"] = "score"
    score: float
    legend: dict[str, Entry]
    probabilities: dict[str, float]
    confidence: float


Answer = Union[NoulAnswer, ChoiceAnswer, ScoreAnswer]


class Usage(BaseModel):
    input_tokens: int
    output_tokens: int


class SystemOneResponse(BaseModel):
    model: str
    answers: dict[str, Answer]
    usage: Usage


class ModelMetadata(BaseModel):
    name: str
    description: str
    release_date: str


class ModelMetadataList(BaseModel):
    models: list[ModelMetadata]

"""Answer assembly: probabilities to typed answers, with TypeSafe's confidence formulas.

The two confidence functions are ported from typesafe-ai/system-one-adapter-python
(MIT License, Copyright (c) 2026 TypeSafe AI) and verified against Jev's published answers
(mean absolute error 0.013 for Choice, 0.005 for Score, within two-decimal rounding).
"""
from __future__ import annotations

from typing import Any, Sequence

from .schema import ChoiceAnswer, NoulAnswer, ScoreAnswer


def _normalize(probs: Sequence[float]) -> list[float]:
    total = float(sum(probs))
    if total <= 0:
        return [1.0 / len(probs)] * len(probs)
    return [float(p) / total for p in probs]


def choice_confidence(probs: Sequence[float]) -> float:
    """Peak probability rescaled from uniform (0) to certainty (1)."""
    if len(probs) == 1:
        return 1.0
    p = _normalize(probs)
    uniform = 1.0 / len(p)
    return (max(p) - uniform) / (1.0 - uniform)


def score_confidence(probs: Sequence[float]) -> float:
    """One minus the probability-weighted mean absolute deviation from the modal level,
    normalised by the mean absolute deviation of the uniform distribution over the levels."""
    if len(probs) == 1:
        return 1.0
    p = _normalize(probs)
    k = len(p)
    mode = max(range(k), key=p.__getitem__)
    distance = sum(pi * abs(i - mode) for i, pi in enumerate(p))
    center = (k - 1) / 2
    uniform_mad = sum(abs(i - center) for i in range(k)) / k
    return max(0.0, 1.0 - distance / uniform_mad)


def expected_score(probs: Sequence[float]) -> float:
    p = _normalize(probs)
    return float(sum(i * pi for i, pi in enumerate(p)))


def _round(x: float, nd: int = 6) -> float:
    return float(round(x, nd))


def make_noul(p_yes: float) -> NoulAnswer:
    return NoulAnswer(noul=_round(min(1.0, max(0.0, float(p_yes)))))


def make_choice(options: Sequence[str], probs: Sequence[float]) -> ChoiceAnswer:
    p = _normalize(probs)
    best = max(range(len(p)), key=p.__getitem__)
    return ChoiceAnswer(
        choice=options[best],
        probabilities={o: _round(pi) for o, pi in zip(options, p)},
        confidence=_round(choice_confidence(p)),
    )


def make_score(levels: Sequence[Any], probs: Sequence[float]) -> ScoreAnswer:
    p = _normalize(probs)
    return ScoreAnswer(
        score=_round(expected_score(p)),
        legend={str(i): lvl for i, lvl in enumerate(levels)},
        probabilities={str(i): _round(pi) for i, pi in enumerate(p)},
        confidence=_round(score_confidence(p)),
    )

"""Rendering: request -> shared prefix text + one suffix per question + answer slots.

Everything the model sees is produced here, so this file is the single place to audit for
leakage of anything the model should not see (question ids, gold labels, internal bookkeeping).
"""
from __future__ import annotations

import json
from dataclasses import dataclass, field
from typing import Any, Sequence

from .schema import ChoiceQuestion, NoulQuestion, Question, ScoreQuestion

PROMPT_VERSION = "qev-labels-v2"

SYSTEM_PROMPT = (
    "Apply the question to the state. Choose exactly one of the listed options. "
    "Respond with only its uppercase letter, with no explanation or reasoning."
)

LETTERS = "ABCDEFGHIJKLMNOPQRSTUVWXYZ"
_NOT_ONE_TOKEN = {"BQ", "BZ", "CJ", "CQ", "CZ", "DQ", "DZ", "EJ", "EY", "FJ", "FQ", "FV", "FZ", "GJ", "GK", "GQ", "GZ",
                  "HJ", "IY", "JF", "JG", "JH", "JL", "JN", "JQ"}
SLOT_LABELS: tuple[str, ...] = tuple(
    list(LETTERS) + [a + b for a in LETTERS for b in LETTERS if a + b not in _NOT_ONE_TOKEN][: 256 - len(LETTERS)])
MAX_SLOTS = len(SLOT_LABELS)


@dataclass(frozen=True)
class PromptStyle:
    """Wording and layout knobs. The default instance is the frozen production template; other
    instances exist only for ablations."""

    name: str = PROMPT_VERSION
    system: str = SYSTEM_PROMPT
    layout: str = "tagged"
    show_names: bool = True
    question_header: str = "Question:"
    score_header: str = "Rate the state:"
    answer_line: str = "Answer with one letter: {letters}."
    answer_line_many: str = "Answer with one label: {letters}."


DEFAULT_STYLE = PromptStyle()

NOUL_DEFAULT_INSTRUCTIONS = "Is the statement true, or is the answer to the question yes?"
NOUL_DEFAULT_TRUE = "the statement is true / the answer is yes"
NOUL_DEFAULT_FALSE = "the statement is false / the answer is no"


def render_entry(entry: Any) -> str:
    """Render an instructions / criteria entry (string, object, array or null) as text."""
    if entry is None:
        return ""
    if isinstance(entry, str):
        return entry.strip()
    return json.dumps(entry, ensure_ascii=False, indent=2)


def render_state(state: Any) -> str:
    if state is None:
        return ""
    if isinstance(state, str):
        return state
    return json.dumps(state, ensure_ascii=False, indent=2)


@dataclass
class RenderedQuestion:
    """One branch: the suffix text and the labels its slots map to."""

    qid: str
    kind: str
    labels: list[str]
    descriptions: list[Any]
    suffix: str
    n_slots: int = field(init=False)

    def __post_init__(self) -> None:
        self.n_slots = len(self.labels)


def _options_block(names: Sequence[str], descriptions: Sequence[Any], show_names: bool = True) -> str:
    lines = []
    for letter, name, desc in zip(SLOT_LABELS, names, descriptions):
        text = render_entry(desc)
        if name is None or (not show_names and text):
            lines.append(f"{letter}. {text}")
        elif text:
            lines.append(f"{letter}. {name}: {text}")
        else:
            lines.append(f"{letter}. {name}")
    return "\n".join(lines)


def render_question(qid: str, q: Question, order: Sequence[int] | None = None, style: PromptStyle = DEFAULT_STYLE) -> RenderedQuestion:
    """Render one question into a suffix. `order` optionally permutes the slot order (used for
    permutation debiasing and training augmentation); labels/descriptions follow the permutation."""
    if isinstance(q, NoulQuestion):
        kind = "noul"
        instructions = render_entry(q.instructions) or NOUL_DEFAULT_INSTRUCTIONS
        crit = q.criteria
        t = render_entry(crit.true) if crit and crit.true is not None else NOUL_DEFAULT_TRUE
        f = render_entry(crit.false) if crit and crit.false is not None else NOUL_DEFAULT_FALSE
        labels, names, descs = ["yes", "no"], ["yes", "no"], [t, f]
    elif isinstance(q, ChoiceQuestion):
        kind = "choice"
        instructions = render_entry(q.instructions) or "Which option applies to the state?"
        labels = list(q.criteria.keys())
        names = list(labels)
        descs = [q.criteria[k] for k in labels]
    elif isinstance(q, ScoreQuestion):
        kind = "score"
        instructions = render_entry(q.instructions) or "Which level describes the state?"
        labels = [str(i) for i in range(len(q.criteria))]
        names = [f"level {i}" for i in range(len(q.criteria))]
        descs = list(q.criteria)
    else:
        raise TypeError(f"unknown question type {type(q)}")

    if len(labels) > MAX_SLOTS:
        raise ValueError(f"{len(labels)} options exceed the {MAX_SLOTS} slots of prompt {PROMPT_VERSION}")

    if order is not None:
        labels = [labels[i] for i in order]
        names = [names[i] for i in order]
        descs = [descs[i] for i in order]

    letters = list(SLOT_LABELS[: len(labels)])
    if style.layout == "json":
        payload = {"criterion": instructions,
                   "options": [{"letter": l, "description": (f"{n}: {render_entry(d)}" if (style.show_names and n is not None and render_entry(d)) else (render_entry(d) or n))}
                               for l, n, d in zip(letters, names, descs)]}
        suffix = json.dumps(payload, ensure_ascii=False)[1:]
    else:
        header = style.question_header if kind != "score" else style.score_header
        suffix = (
            f"{header} {instructions}\n\n"
            f"Options:\n{_options_block(names, descs, style.show_names)}\n\n"
            + (style.answer_line if len(letters) <= len(LETTERS) else style.answer_line_many).format(letters=", ".join(letters))
        )
    return RenderedQuestion(qid=qid, kind=kind, labels=labels, descriptions=descs, suffix=suffix)


def state_block(state: Any, style: PromptStyle = DEFAULT_STYLE) -> str:
    if style.layout == "json":
        return "{" + json.dumps({"evidence": state}, ensure_ascii=False)[1:-1] + ", "
    return f"<state>\n{render_state(state)}\n</state>\n\n"


def build_messages(state: Any, suffix: str, style: PromptStyle = DEFAULT_STYLE) -> list[dict[str, str]]:
    """Chat messages for one branch. The user turn is `state_block + suffix`, so every branch of a
    request shares the same prefix up to the end of the state block."""
    return [
        {"role": "system", "content": style.system},
        {"role": "user", "content": state_block(state, style) + suffix},
    ]

"""Calibration: temperatures per (primitive, option count), fitting, and probability metrics."""
from __future__ import annotations

import json
import logging
import math
from dataclasses import dataclass, field
from pathlib import Path
from typing import Sequence


@dataclass
class Calibration:
    """Temperature table. Keys are "kind" or "kind:K". Missing keys fall back to the primitive-level
    temperature, then to 1.0."""

    temperatures: dict[str, float] = field(default_factory=dict)
    source: str = "none"

    def temperature(self, kind: str, k: int) -> float:
        return self.temperatures.get(f"{kind}:{k}", self.temperatures.get(kind, 1.0))

    @classmethod
    def load(cls, path: str | Path) -> "Calibration":
        data = json.loads(Path(path).read_text())
        return cls(temperatures={k: float(v) for k, v in data.get("temperatures", {}).items()}, source=str(path))

    def save(self, path: str | Path) -> None:
        from .prompt import PROMPT_VERSION

        Path(path).write_text(json.dumps({"temperatures": self.temperatures, "source": self.source,
                                          "prompt_version": PROMPT_VERSION}, indent=2))


def softmax(logits: Sequence[float], temperature: float = 1.0) -> list[float]:
    z = [float(x) / temperature for x in logits]
    m = max(z)
    w = [math.exp(x - m) for x in z]
    s = sum(w)
    return [x / s for x in w]


def fit_temperature(logits: Sequence[Sequence[float]], targets: Sequence[Sequence[float]],
                    lo: float = 0.05, hi: float = 50.0, iters: int = 60) -> float:
    """Fit one scalar temperature by minimising cross-entropy against (possibly soft) targets.
    Golden-section search on log T; no torch dependency so it runs anywhere."""
    def nll(t: float) -> float:
        total = 0.0
        for z, y in zip(logits, targets):
            p = softmax(z, t)
            total -= sum(yi * math.log(max(pi, 1e-12)) for yi, pi in zip(y, p))
        return total / max(len(logits), 1)

    a, b = math.log(lo), math.log(hi)
    gr = (math.sqrt(5) - 1) / 2
    c, d = b - gr * (b - a), a + gr * (b - a)
    fc, fd = nll(math.exp(c)), nll(math.exp(d))
    for _ in range(iters):
        if fc < fd:
            b, d, fd = d, c, fc
            c = b - gr * (b - a)
            fc = nll(math.exp(c))
        else:
            a, c, fc = c, d, fd
            d = a + gr * (b - a)
            fd = nll(math.exp(d))
    t = math.exp((a + b) / 2)
    if t >= hi * 0.99 or t <= lo * 1.01:
        logging.getLogger("qev.calibrate").warning(
            "temperature fit hit the %s bound (T=%.4f) on %d rows; the slot logits likely carry no signal for this group",
            "upper" if t >= hi * 0.99 else "lower", t, len(logits))
    return t


def ece(confidences: Sequence[float], correct: Sequence[float], n_bins: int = 15) -> float:
    n = len(confidences)
    if n == 0:
        return 0.0
    total = 0.0
    for b in range(n_bins):
        lo, hi = b / n_bins, (b + 1) / n_bins
        idx = [i for i, c in enumerate(confidences) if (lo < c <= hi) or (b == 0 and c <= lo)]
        if idx:
            avg_conf = sum(confidences[i] for i in idx) / len(idx)
            avg_acc = sum(correct[i] for i in idx) / len(idx)
            total += len(idx) / n * abs(avg_conf - avg_acc)
    return total


def adaptive_ece(confidences: Sequence[float], correct: Sequence[float], n_bins: int = 15) -> float:
    n = len(confidences)
    if n == 0:
        return 0.0
    order = sorted(range(n), key=lambda i: confidences[i])
    total = 0.0
    size = max(1, n // n_bins)
    for start in range(0, n, size):
        idx = order[start:start + size]
        avg_conf = sum(confidences[i] for i in idx) / len(idx)
        avg_acc = sum(correct[i] for i in idx) / len(idx)
        total += len(idx) / n * abs(avg_conf - avg_acc)
    return total


def brier(probs: Sequence[float], target: Sequence[float]) -> float:
    return sum((p - t) ** 2 for p, t in zip(probs, target))


def nll(probs: Sequence[float], target: Sequence[float]) -> float:
    return -sum(t * math.log(max(p, 1e-12)) for p, t in zip(probs, target))


def tvd(p: Sequence[float], q: Sequence[float]) -> float:
    return 0.5 * sum(abs(a - b) for a, b in zip(p, q))

